const tasksByRef = `-- name: TasksByRef :many
SELECT k.id, (t.key || '-' || k.number)::text AS ref, k.title,
    s.name AS status_name, s.color AS status_color, s.category AS status_category
FROM tasks k
JOIN teams t ON t.id = k.team_id
JOIN task_statuses s ON s.id = k.status_id
WHERE (t.key || '-' || k.number) = ANY($1::text[])
  AND ($2::bool OR EXISTS (SELECT 1 FROM team_members tm WHERE tm.team_id = k.team_id AND tm.user_id = $3))
`

